// hosts 文件优先于 DNS：本地排查时常用它把域名指到测试机
data, err := os.ReadFile("/etc/hosts")
if err != nil {
	fmt.Println("读取 hosts 失败:", err)
	return
}
for _, line := range strings.Split(string(data), "\n") {
	if strings.HasPrefix(line, "127.0.0.1") {
		fmt.Println("本机覆盖:", strings.TrimSpace(line))
	}
}

// 常见 DNS 记录类型和它们表达的信息
type record struct {
	typ   string // A、AAAA、CNAME、MX、TXT、NS
	name  string // 域名
	value string // 地址、别名目标、邮件服务器、文本
	ttl   uint32 // 缓存秒数
}

r := record{typ: "MX", name: "example.com", value: "mail.example.com", ttl: 300}
fmt.Println(r.typ, r.name, "->", r.value, r.ttl)

// CNAME 链：解析器要一直追到最后的 A 记录
chain := map[string]string{
	"www.example.com": "cdn.vendor.net",
	"cdn.vendor.net":  "203.0.113.20",
}
name := "www.example.com"
for i := 0; i < 5; i++ {
	next, ok := chain[name]
	if !ok {
		break
	}
	fmt.Println(name, "->", next)
	name = next
}

// 轮询选节点：只是把索引在节点列表里转圈
nodes := []string{"10.0.0.1", "10.0.0.2", "10.0.0.3"}
index := 2 // 上次用到的下标
index = (index + 1) % len(nodes)
fmt.Println("本次选中:", nodes[index])

// 带 TTL 的缓存条目：过期后就不再返回旧结果
type entry struct {
	value   string
	expires time.Time
}

cached := entry{value: "203.0.113.10", expires: time.Now().Add(60 * time.Second)}
if time.Now().Before(cached.expires) {
	fmt.Println("命中缓存:", cached.value)
} else {
	fmt.Println("缓存已过期，需要重新查询")
}

// TLS 1.3 握手里客户端依次看到的消息
stages := []string{
	"ClientHello",
	"ServerHello",
	"EncryptedExtensions",
	"Certificate",
	"CertificateVerify",
	"Finished",
}
for _, s := range stages {
	fmt.Println(s)
}

// SNI：服务端按 ClientHello 里的主机名挑证书
certs := map[string]string{
	"a.example.com": "a.crt",
	"b.example.com": "b.crt",
}
sni := "b.example.com"
fmt.Println("为", sni, "下发证书:", certs[sni])

// TLS 1.3 只保留 AEAD 套件
suites := []string{
	"TLS_AES_128_GCM_SHA256",
	"TLS_AES_256_GCM_SHA384",
	"TLS_CHACHA20_POLY1305_SHA256",
}
for _, s := range suites {
	fmt.Println(s)
}
